import React, { memo } from 'react';
import {
  Box,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Typography,
  Button,
  IconButton,
  Tooltip,
} from '@mui/material';
import type { Theme } from '@mui/material/styles';
import { HelpOutline as HelpOutlineIcon } from '@mui/icons-material';
import { PluginDialogHeader } from './PluginDialogHeader.js';
import { PluginDialogFooter, type PluginDialogFooterProps } from './PluginDialogFooter.js';
import type { DialogActionInFlight } from '../types.js';

export type DialogHelpButtonPlacement = 'header' | 'content';

export interface DialogHelpButtonConfig {
  placement: DialogHelpButtonPlacement;
  onClick: () => void;
  tooltip?: string;
}

export const createHeaderComponent = (
  title: string,
  subtitle: string | undefined,
  icon: React.ReactNode | undefined,
  pendingAction: DialogActionInFlight | null,
  helpButton?: DialogHelpButtonConfig,
) =>
  memo(() => (
    <PluginDialogHeader
      title={title}
      subtitle={subtitle}
      icon={icon || undefined}
      pendingAction={pendingAction}
      helpButton={helpButton?.placement === 'header' ? helpButton : undefined}
    />
  ));

export const createContentComponent = (
  dialogRef: React.RefObject<HTMLElement | null>,
  helpButton?: DialogHelpButtonConfig,
) =>
  memo(
    function DialogContentWrapper(props: React.PropsWithChildren) {
      return (
        <Box
          sx={(theme: Theme) => ({
            flex: 1,
            overflow: 'auto',
            padding: theme.spacing(2),
            position: 'relative',
          })}
          ref={dialogRef}
        >
          {helpButton?.placement === 'content' ? (
            <Tooltip title={helpButton.tooltip ?? 'Open guided tour'}>
              <IconButton
                onClick={helpButton.onClick}
                size="small"
                sx={{
                  position: 'absolute',
                  left: 8,
                  bottom: 8,
                  color: 'text.secondary',
                  '&:hover': { backgroundColor: 'action.hover' },
                }}
                aria-label={helpButton.tooltip ?? 'Open guided tour'}
              >
                <HelpOutlineIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          ) : null}
          {props.children}
        </Box>
      );
    },
  );

export const createFooterComponent = (footerPropsRef: React.MutableRefObject<PluginDialogFooterProps>) =>
  memo(function DialogFooterWrapper() {
    return <PluginDialogFooter {...footerPropsRef.current} />;
  });

export interface ConflictDialogProps {
  open: boolean;
  updatedAt: number | null;
  foregroundSx: Record<string, unknown>;
  resolveConflict: (action: 'continue' | 'discard') => void;
  formatTimestamp: (ts?: number) => string;
  translate: (key: string, opts?: Record<string, unknown>) => string;
}

export const ConflictDialog: React.FC<ConflictDialogProps> = ({
  open,
  updatedAt,
  foregroundSx,
  resolveConflict,
  formatTimestamp,
  translate,
}) => {
  return (
    <Dialog
      open={open}
      onClose={() => {
        resolveConflict('continue');
      }}
      sx={{
        ...foregroundSx,
        zIndex: (theme) => (theme.zIndex?.modal ?? 1300) + 1001,
      }}
      slotProps={{
        backdrop: {
          sx: {
            backgroundColor: 'rgba(9, 12, 28, 0.45)',
            zIndex: (theme) => (theme.zIndex?.modal ?? 1300) + 1000,
          },
        },
        paper: {
          sx: { zIndex: (theme) => (theme.zIndex?.modal ?? 1300) + 1002 },
        },
      }}
    >
      <DialogTitle>{translate('dialogs.pluginDraft.conflict.title')}</DialogTitle>
      <DialogContent>
        <Typography variant="body2">
          {translate('dialogs.pluginDraft.conflict.description', {
            timestamp: formatTimestamp(updatedAt ?? undefined),
          })}
        </Typography>
      </DialogContent>
      <DialogActions>
        <Button
          color="secondary"
          onClick={() => {
            resolveConflict('discard');
          }}
        >
          {translate('dialogs.pluginDraft.conflict.buttons.discardSelf')}
        </Button>
        <Button
          variant="contained"
          onClick={() => {
            resolveConflict('continue');
          }}
        >
          {translate('dialogs.pluginDraft.conflict.buttons.keepSelf')}
        </Button>
      </DialogActions>
    </Dialog>
  );
};
