import { useCallback, useMemo } from 'react';
import { useDialogContext } from '@hierarchidb/ui-dialog';
import { useLocation } from '@tanstack/react-router';
import type { DialogActionInFlight } from '../../types.js';

type WorkerStepState = { id: string; enabled?: boolean; completed?: boolean; error?: string | null };
type WorkerDialogState = { steps?: WorkerStepState[] };

export function usePluginDialogHeaderLogic(params: {
  dialogState?: WorkerDialogState | null;
  pendingAction?: DialogActionInFlight | null;
}) {
  const { dialogState, pendingAction } = params;
  const ctx = useDialogContext<Record<string, unknown>>();
  const location = useLocation();

  const navigationLocked = Boolean(pendingAction);

  const workerStepMap = useMemo(() => {
    const steps = dialogState?.steps;
    if (!steps?.length) return null;
    const map = new Map<string, WorkerStepState>();
    steps.forEach((step) => {
      map.set(step.id, step);
    });
    return map;
  }, [dialogState?.steps]);

  const toggleMaximize = useCallback(() => {
    const next = ctx.displayMode === 'maximize' ? 'normal' : 'maximize';
    ctx.onDisplayModeChange?.(next);
  }, [ctx]);

  const toggleFullscreen = useCallback(() => {
    const next = ctx.displayMode === 'full-screen' ? 'normal' : 'full-screen';
    ctx.onDisplayModeChange?.(next);
  }, [ctx]);

  const buildStepLink = useCallback(
    (index: number) => {
      const stepNumber = index + 1;
      const fallbackPath = (() => {
        if (typeof window === 'undefined') return '/';
        const hashValue = window.location.hash || '';
        if (!hashValue.startsWith('#/')) return '/';
        const hashPath = hashValue.slice(1);
        const [pathPart] = hashPath.split('?');
        return pathPart || '/';
      })();
      const rawPath = location.pathname || '';
      const pathCandidate = rawPath && rawPath.startsWith('/') ? rawPath : rawPath ? `/${rawPath}` : '';
      const candidateSegments = pathCandidate.replace(/^\/+|\/+$/g, '').split('/').filter(Boolean);
      const shouldUseHash = candidateSegments[0] !== 't' || candidateSegments.length < 6;
      const hashPath = fallbackPath || '/';
      const resolvedPath = shouldUseHash ? hashPath : pathCandidate;
      const basePath = resolvedPath && resolvedPath.startsWith('/') ? resolvedPath : `/${resolvedPath}`;
      const searchSuffix = location.searchStr ?? '';
      const segments = basePath.replace(/^\/+|\/+$/g, '').split('/').filter(Boolean);
      if (segments.length < 6 || segments[0] !== 't') {
        return `${basePath}${searchSuffix}`;
      }
      const baseSegments = segments.slice(0, 6);
      const modeCandidate = segments[6];
      const currentMode = modeCandidate === 'full' || modeCandidate === 'normal' ? modeCandidate : undefined;
      const includeMode = currentMode === 'full';
      const includeStep = stepNumber > 1;
      const nextSegments = [...baseSegments];
      if (includeMode) nextSegments.push(currentMode);
      if (includeStep) nextSegments.push(String(stepNumber));
      const nextPath = `/${nextSegments.join('/')}`;
      return `${nextPath}${searchSuffix}`;
    },
    [location.pathname, location.searchStr]
  );

  const handleStepClick = useCallback(
    (event: React.MouseEvent | React.KeyboardEvent, index: number, canNavigate: boolean) => {
      if (!canNavigate || index === ctx.activeStepIndex || navigationLocked) {
        event.preventDefault();
        return;
      }
      ctx.onStepNavigate({ type: 'direct', targetIndex: index });
    },
    [ctx, navigationLocked]
  );

  return {
    ctx,
    workerStepMap,
    navigationLocked,
    toggleMaximize,
    toggleFullscreen,
    buildStepLink,
    handleStepClick,
  };
}
